public sealed class NativeContinualLearner:IDisposable
{
    private const int MaximumQueuedSequences=64; public const int M3WarmupFreshSequences=0;
    private readonly ConcurrentQueue<NativeCompletedSequence> queue=new ConcurrentQueue<NativeCompletedSequence>();
    private readonly ConcurrentQueue<NativeTrainingResult> results=new ConcurrentQueue<NativeTrainingResult>();
    private readonly AutoResetEvent signal=new AutoResetEvent(false);private readonly Thread worker;private volatile bool stopping;private int queued;
    private readonly object stateLock=new object();private readonly Dictionary<string,NativeM3LearningState> states;
    private readonly Func<string,NativeCreatureModel> resolveModel;
    private readonly NativeCreatureModel sharedM2Model;private NativeSharedLearningState shared;
    public int QueueDepth=>Volatile.Read(ref queued);public int Dropped{get;private set;}public bool Busy{get;private set;}
    public int ReplayCount{get{lock(stateLock)return shared?.m3?.replay?.Count??0;}}
    public int UsefulReplayCount{get{lock(stateLock)return shared?.m3?.usefulReplay?.Count??0;}}

    public NativeContinualLearner(NativeBrainWeights sharedM2Seed,NativeDynamicsWeights sharedM3Seed,Func<string,NativeCreatureModel> resolver)
    {states=new Dictionary<string,NativeM3LearningState>(StringComparer.Ordinal);shared=new NativeSharedLearningState{m2=(sharedM2Seed??NativeBrainWeights.Create(7331)).Clone(),m3=new NativeM3LearningState{dynamics=(sharedM3Seed??NativeDynamicsWeights.Create(7332)).Clone()}};sharedM2Model=new NativeCreatureModel(shared.m2,7331);resolveModel=resolver;worker=new Thread(Run){IsBackground=true,Name="Native continual learner"};worker.Start();}
    public bool Enqueue(NativeCompletedSequence sample){if(sample==null)return false;if(Interlocked.Increment(ref queued)>MaximumQueuedSequences){Interlocked.Decrement(ref queued);Dropped++;return false;}queue.Enqueue(sample.Clone());signal.Set();return true;}
    public void RecordEvaluation(NativeCompletedSequence sample){if(sample==null)return;lock(stateLock){shared.m3.validation.Add(sample.Clone());if(shared.m3.validation.Count>128)shared.m3.validation.RemoveAt(0);}}
    public bool TryResult(out NativeTrainingResult result)=>results.TryDequeue(out result);
    public NativeDynamicsWeights Snapshot(string controllerId){lock(stateLock)return shared.m3.dynamics.Clone();}
    public NativeBrainWeights SnapshotM2(){lock(stateLock)return shared.m2.Clone();}
    public NativeM3LearningState Capture(string controllerId){lock(stateLock)return shared.m3.Clone();}
    public NativeSharedLearningState CaptureShared(){lock(stateLock)return shared.Clone();}
    public void RestoreShared(NativeSharedLearningState value){if(value==null||value.m2==null||value.m3?.dynamics==null)return;lock(stateLock){shared=value.Clone();sharedM2Model.RepairFrom(shared.m2);}}
    public Dictionary<string,NativeM3LearningState> CaptureAll(){lock(stateLock)return new Dictionary<string,NativeM3LearningState>{{"shared",shared.m3.Clone()}};}
    public void SetState(string controllerId,NativeM3LearningState state){}
    public void RemoveState(string controllerId){}
    private void Run()
    {
        while(!stopping){if(!queue.TryDequeue(out NativeCompletedSequence fresh)){signal.WaitOne(50);continue;}Interlocked.Decrement(ref queued);Busy=true;long started=System.Diagnostics.Stopwatch.GetTimestamp();var result=new NativeTrainingResult{controllerId=fresh.controllerId};try{
            NativeDynamicsWeights m3Snapshot;List<NativeCompletedSequence> m3Batch,m2Replay;NativeOptimizerState optimizer;NativeSynapticIntelligence protection;lock(stateLock){NativeM3LearningState state=shared.m3;m3Batch=new List<NativeCompletedSequence>{fresh};m3Batch.AddRange(state.replay.Sample(7));m2Replay=state.usefulReplay.Sample(2);m2Replay.AddRange(state.replay.Sample(Math.Max(0,7-m2Replay.Count)));state.replay.Offer(fresh);if(IsUsefulMovement(fresh))state.usefulReplay.Offer(fresh);m3Snapshot=state.dynamics.Clone();optimizer=state.optimizer.Clone();protection=state.protection.Clone();}result.m3=NativeCreatureModel.TrainSharedM3Batch(m3Batch,m3Snapshot,optimizer,protection);if(!m3Snapshot.IsFinite()||!protection.IsFinite())throw new InvalidOperationException("M3 update produced invalid state");
            {var observations=new List<NativeObservation>{fresh.observation};observations.AddRange(m2Replay.Select(s=>s.observation));result.m2=sharedM2Model.TrainM2Batch(observations,m3Snapshot,fresh.observation.tick);}
            lock(stateLock){shared.m3.dynamics=m3Snapshot;shared.m3.optimizer=optimizer;shared.m3.protection=protection;shared.m3.freshSequences++;shared.m3.optimizerSteps=result.m3.optimizerSteps;shared.m2=sharedM2Model.Weights.Clone();shared.m2Optimizer=sharedM2Model.M2Optimizer.Clone();shared.m2Protection=sharedM2Model.M2Protection.Clone();shared.modelVersion++;if(shared.m3.optimizerSteps%128==0)result.evaluation=NativeCreatureModel.EvaluateM3(shared.m3.validation,m3Snapshot,shared.m3.optimizerSteps);}
        }catch(Exception e){result.error=e.ToString();}finally{result.milliseconds=(long)((System.Diagnostics.Stopwatch.GetTimestamp()-started)*1000d/System.Diagnostics.Stopwatch.Frequency);results.Enqueue(result);Busy=false;}}
    }
    public void Dispose(){stopping=true;signal.Set();if(worker.IsAlive)worker.Join(2000);signal.Dispose();}
    private static bool IsUsefulMovement(NativeCompletedSequence sample){if(sample?.observation==null||sample.actualPoses==null||sample.actualAuxiliary==null)return false;int last=(NativeCreatureModel.PlanningHorizon-1)*NativeCreatureModel.PoseValueCount;Vector2 end=new Vector2(sample.actualPoses[last],sample.actualPoses[last+1]);float improvement=sample.observation.goal.magnitude-(sample.observation.goal-end).magnitude;int aux=(NativeCreatureModel.PlanningHorizon-1)*NativeCreatureModel.AuxiliaryValueCount+NativeCreatureModel.MaxLimbs*NativeCreatureModel.EndpointValueCount;bool contact=false;for(int limb=0;limb<sample.observation.limbCount;limb++)contact|=sample.actualAuxiliary[aux+limb*NativeCreatureModel.ContactValueCount]>.5f;return improvement>=.05f&&contact;}
}

// v26 movement school.  This is intentionally a plain-C# learner: Unity owns
// physics and observations, while this class owns the only published M2/M3
// snapshot.  Rollouts always use an immutable clone of that snapshot.
[Serializable]
public sealed class NativeMovementWeights
{
    public const int Width=64,HistoryLength=4,NodeInput=HistoryLength*NativeCreatureModel.JointFeatureSize+NativeCreatureModel.PositionEncodingSize+4,GlobalInput=25,PolicyLimbOutputs=4,TargetSize=66,M3Input=Width+NativeCreatureModel.MaxLimbs+3;
    [JsonIgnore] public float[] nodeInput,nodeBias,messageSelf,messageParent,messageChild,messageBias,frequency,limbPolicy,value,m3Head0,m3Head1,m3Head2,m3Bias0,m3Bias1,m3Bias2,inverse,logStd;
    public static NativeMovementWeights Create(int seed)
    {
        var r=new System.Random(seed);int w=Width,t=TargetSize,m3in=M3Input;
        return new NativeMovementWeights{nodeInput=Xavier(r,NodeInput,w),nodeBias=new float[w],messageSelf=Xavier(r,w,w),messageParent=Xavier(r,w,w),messageChild=Xavier(r,w,w),messageBias=new float[w],frequency=Xavier(r,w+GlobalInput,1),limbPolicy=Xavier(r,w+GlobalInput,PolicyLimbOutputs),value=Xavier(r,w+GlobalInput,1),m3Head0=Xavier(r,m3in,t),m3Head1=Xavier(r,m3in,t),m3Head2=Xavier(r,m3in,t),m3Bias0=new float[t],m3Bias1=new float[t],m3Bias2=new float[t],inverse=Xavier(r,m3in,1),logStd=Enumerable.Repeat(-.7f,1+NativeCreatureModel.MaxLimbs*PolicyLimbOutputs).ToArray()};
    }
    public NativeMovementWeights Clone(){var c=new NativeMovementWeights();foreach(var f in typeof(NativeMovementWeights).GetFields().Where(f=>f.FieldType==typeof(float[]))){float[] a=(float[])f.GetValue(this);f.SetValue(c,a==null?null:(float[])a.Clone());}return c;}
    public IEnumerable<KeyValuePair<string,float[]>> Parameters(){foreach(var f in typeof(NativeMovementWeights).GetFields().Where(f=>f.FieldType==typeof(float[])))yield return new KeyValuePair<string,float[]>(f.Name,(float[])f.GetValue(this));}
    public bool IsFinite()=>Parameters().All(p=>p.Value!=null&&p.Value.All(NativeCreatureModel.IsFinite));
    private static float[] Xavier(System.Random r,int input,int output){float[] a=new float[input*output];double s=Math.Sqrt(6d/(input+output));for(int i=0;i<a.Length;i++)a[i]=(float)((r.NextDouble()*2d-1d)*s);return a;}
}

