    public bool Enqueue(NativeMovementTransition transition){if(transition==null)return false;if(Interlocked.Increment(ref queued)>2048){Interlocked.Decrement(ref queued);Dropped++;return false;}queue.Enqueue(transition.Clone());signal.Set();return true;}
