    public NativePolicyDecision Decide(NativeMovementObservation observation,bool refreshRhythm,bool stochastic,NativeMovementWeights frozenEvaluationWeights=null)
    {
        NativeMovementWeights w;int version;bool curiosityReady;lock(stateLock){w=frozenEvaluationWeights?.Clone()??published.Clone();version=state.modelVersion;curiosityReady=allowCuriosity&&frozenEvaluationWeights==null&&state.curiosityReady&&!state.simpleBodyQualified;}NativeGraphCache c=ForwardGraph(observation,w);int dims=1+NativeCreatureModel.MaxLimbs*NativeMovementWeights.PolicyLimbOutputs;float[] mean=new float[dims],sample=new float[dims];mean[0]=Dense(c.policyContext,w.frequency,1,0)[0];for(int l=0;l<observation.limbCount;l++){float[] context=Concat(c.state[3][l],c.global);float[] limb=Dense(context,w.limbPolicy,NativeMovementWeights.PolicyLimbOutputs,0);for(int k=0;k<NativeMovementWeights.PolicyLimbOutputs;k++)mean[1+l*NativeMovementWeights.PolicyLimbOutputs+k]=limb[k];}
