    }
    public static float GaussianLogProbability(float sample,float mean,float std){float z=(sample-mean)/Mathf.Max(1e-6f,std);return -.5f*z*z-Mathf.Log(Mathf.Max(1e-6f,std))-.5f*Mathf.Log(2f*Mathf.PI);}
    public static float GaussianMeanGradient(float sample,float mean,float std)=>(sample-mean)/Mathf.Max(1e-6f,std*std);
