    private void Run(){while(!stopping){if(!queue.TryDequeue(out NativeMovementTransition t)){signal.WaitOne(50);continue;}Interlocked.Decrement(ref queued);Busy=true;try{NativeMovementMetrics metrics;lock(stateLock){Offer(t);if(t.evaluation)metrics=EvaluateHeldOut(t);else{rollout.Enqueue(t);metrics=trainM3?TrainDynamics(t):new NativeMovementMetrics{policyUpdates=state.policyUpdates,m3Updates=state.m3Updates,batchSize=1};if(rollout.Count>=RolloutSize){List<NativeMovementTransition> batch=new List<NativeMovementTransition>();while(batch.Count<RolloutSize&&rollout.TryDequeue(out var x))batch.Add(x);TrainPpo(batch,metrics);state.modelVersion++;}state.freshTransitions++;state.curiosityReady=trainM3&&allowCuriosity&&state.freshTransitions>=512&&metrics.inverseAccuracy>=.55f;}}results.Enqueue(metrics);}catch(Exception){Dropped++;}finally{Busy=false;}}}
