    private void AddBalancedImitation(NativeMovementTransition t){string key=(t.bodySignature??"")+":"+Math.Sign(t.observation?.command.x??0f);List<NativeMovementTransition> same=state.imitation.Where(x=>(x.bodySignature??"")+":"+Math.Sign(x.observation?.command.x??0f)==key).ToList();if(same.Count>=128)state.imitation.Remove(same[0]);AddBounded(state.imitation,t,SpecialReplayCapacity);}
    private static NativeMovementTransition Aggregate(List<NativeMovementTransition> steps,int horizon){NativeMovementTransition first=steps[0].Clone(),last=steps[steps.Count-1];first.nextObservation=last.nextObservation?.Clone();first.horizonSteps=horizon;first.torsoDeltaX=steps.Sum(x=>x.torsoDeltaX);first.torsoDeltaY=steps.Sum(x=>x.torsoDeltaY);first.headingDelta=steps.Sum(x=>x.headingDelta);first.angularVelocityDelta=last.angularVelocityDelta;first.reward=steps.Sum(x=>x.reward);first.travelReward=steps.Sum(x=>x.travelReward);first.effortPenalty=steps.Sum(x=>x.effortPenalty);first.curiosityReward=steps.Sum(x=>x.curiosityReward);first.contactTransition=steps.Any(x=>x.contactTransition);first.terminal=last.terminal;if(first.decision?.executed!=null)for(int i=0;i<first.decision.executed.Length;i++)first.decision.executed[i]=steps.Average(x=>x.decision?.executed!=null&&i<x.decision.executed.Length?x.decision.executed[i]:0f);return first;}
    private static void AddBounded(List<NativeMovementTransition> list,NativeMovementTransition t,int capacity){if(list.Count>=capacity)list.RemoveAt(0);list.Add(t.Clone());}
    private NativeMovementMetrics TrainDynamics(NativeMovementTransition fresh)
