    private static float PhysicalGroupWeight(int index,int limbs){limbs=Mathf.Max(1,limbs);if(index<6)return 1f/(5f*6f);int channel=(index-6)%10;if(channel<2)return 1f/(5f*2f*limbs);if(channel<6)return 1f/(5f*4f*limbs);if(channel<9)return 1f/(5f*3f*limbs);return 1f/(5f*limbs);}
    private static void AddGeometryConsistency(NativeMovementTransition t,float[] prediction,float[] gradient)
    {
