    private static float[] EnsemblePrediction(float[] input,NativeMovementWeights w){float[][] p={Dense(input,w.m3Head0,NativeMovementWeights.TargetSize,0,w.m3Bias0),Dense(input,w.m3Head1,NativeMovementWeights.TargetSize,0,w.m3Bias1),Dense(input,w.m3Head2,NativeMovementWeights.TargetSize,0,w.m3Bias2)};float[] mean=new float[NativeMovementWeights.TargetSize];for(int i=0;i<mean.Length;i++)mean[i]=(p[0][i]+p[1][i]+p[2][i])/3f;return mean;}
