    private void TrainSelfImitation(){if(state.imitation.Count==0)return;var gradients=Zero(state.weights);List<NativeMovementTransition> samples=state.imitation.Skip(Math.Max(0,state.imitation.Count-16)).ToList();foreach(var t in samples){NativeGraphCache c=ForwardGraph(t.observation,state.weights);float[] mean=PolicyMean(c,state.weights,t.observation.limbCount),target=t.decision.sample,gradient=new float[mean.Length];for(int i=0;i<mean.Length;i++)if(DimensionActive(i,t.decision.sampledRhythm,t.observation.limbCount))gradient[i]=ImitationCoefficient*(mean[i]-target[i]);BackpropPolicy(c,gradient,0f,state.weights,gradients);}Scale(gradients,1f/samples.Count);ApplyAdam(state.weights,gradients,state.optimizer,LearningRate,.5f);}
