    private static void BackpropPolicy(NativeGraphCache c,float[] meanGrad,float valueGrad,NativeMovementWeights w,Dictionary<string,float[]> g){float[] pooledGrad=new float[NativeMovementWeights.Width];float[] contextGrad=DenseBackward(c.policyContext,new[]{meanGrad[0]},w.frequency,g["frequency"],null);Add(pooledGrad,contextGrad);contextGrad=DenseBackward(c.policyContext,new[]{valueGrad},w.value,g["value"],null);Add(pooledGrad,contextGrad);float[][] nodeGrad=Enumerable.Range(0,c.observation.limbCount).Select(_=>new float[NativeMovementWeights.Width]).ToArray();for(int l=0;l<c.observation.limbCount;l++){float[] og=new float[NativeMovementWeights.PolicyLimbOutputs];Array.Copy(meanGrad,1+l*NativeMovementWeights.PolicyLimbOutputs,og,0,og.Length);float[] ig=DenseBackward(Concat(c.state[3][l],c.global),og,w.limbPolicy,g["limbPolicy"],null);Add(nodeGrad[l],ig);}for(int l=0;l<nodeGrad.Length;l++)for(int h=0;h<NativeMovementWeights.Width;h++)nodeGrad[l][h]+=pooledGrad[h]/Mathf.Max(1,nodeGrad.Length);BackwardGraph(c,nodeGrad,w,g);}
    private static NativeGraphCache ForwardGraph(NativeMovementObservation o,NativeMovementWeights w){int n=Mathf.Clamp(o.limbCount,0,NativeCreatureModel.MaxLimbs);var c=new NativeGraphCache{observation=o,input=new float[n][],state=new float[4][][],parent=new int[n]};c.state[0]=new float[n][];NativeObservation current=o.history?.LastOrDefault(x=>x!=null);for(int l=0;l<n;l++){float[] x=new float[NativeMovementWeights.NodeInput];int at=0;for(int f=0;f<NativeMovementWeights.HistoryLength;f++){NativeObservation frame=o.history!=null&&f<o.history.Length?o.history[f]:null;for(int j=0;j<NativeCreatureModel.JointFeatureSize;j++)x[at++]=frame?.jointFeatures?[l*NativeCreatureModel.JointFeatureSize+j]??0f;}for(int j=0;j<NativeCreatureModel.PositionEncodingSize;j++)x[at++]=current?.positionEncodings?[l*NativeCreatureModel.PositionEncodingSize+j]??0f;int held=1+l*3;x[at++]=o.heldRhythm!=null&&held<o.heldRhythm.Length?o.heldRhythm[held]/8f:0f;x[at++]=o.heldRhythm!=null&&held+1<o.heldRhythm.Length?o.heldRhythm[held+1]/Mathf.PI:0f;x[at++]=o.heldRhythm!=null&&held+2<o.heldRhythm.Length?o.heldRhythm[held+2]/8f:0f;x[at]=current?.jointFeatures?[l*NativeCreatureModel.JointFeatureSize+18]??0f;c.input[l]=x;c.state[0][l]=Activate(Dense(x,w.nodeInput,NativeMovementWeights.Width,0,w.nodeBias));c.parent[l]=FindParent(current,l);}
        for(int round=1;round<=3;round++){c.state[round]=new float[n][];for(int l=0;l<n;l++){float[] z=Dense(c.state[round-1][l],w.messageSelf,NativeMovementWeights.Width,0,w.messageBias);int p=c.parent[l];if(p>=0)Add(z,Dense(c.state[round-1][p],w.messageParent,NativeMovementWeights.Width,0));int children=0;float[] child=new float[NativeMovementWeights.Width];for(int k=0;k<n;k++)if(c.parent[k]==l){Add(child,c.state[round-1][k]);children++;}if(children>0){for(int h=0;h<child.Length;h++)child[h]/=children;Add(z,Dense(child,w.messageChild,NativeMovementWeights.Width,0));}c.state[round][l]=Activate(z);}}
        c.pooled=new float[NativeMovementWeights.Width];for(int l=0;l<n;l++)Add(c.pooled,c.state[3][l]);if(n>0)for(int h=0;h<c.pooled.Length;h++)c.pooled[h]/=n;c.global=GlobalFeatures(o,current);c.policyContext=Concat(c.pooled,c.global);return c;}
    private static int FindParent(NativeObservation o,int limb){if(o?.parentSlots==null||limb>=o.parentSlots.Length)return -1;int innovation=o.parentSlots[limb];if(innovation<=0)return -1;for(int i=0;i<limb;i++)if(o.parentSlots[i]==innovation)return i;return innovation-1<limb?innovation-1:-1;}
    private static float[] GlobalFeatures(NativeMovementObservation o,NativeObservation current){float[] g=new float[NativeMovementWeights.GlobalInput];if(current?.torsoWithoutGoal!=null)Array.Copy(current.torsoWithoutGoal,2,g,0,Math.Min(16,current.torsoWithoutGoal.Length-2));g[16]=o.angularVelocity/720f;g[17]=o.gravityLocal.x;g[18]=o.gravityLocal.y;g[19]=o.command.x;g[20]=o.command.y;g[21]=o.oscillatorSin;g[22]=o.oscillatorCos;g[23]=o.rhythmTicksRemaining/RhythmActionTicks;g[24]=o.heldRhythm!=null&&o.heldRhythm.Length>0?o.heldRhythm[0]/3f:0f;return g;}
    private static float[] PolicyMean(NativeGraphCache c,NativeMovementWeights w,int limbs){float[] r=new float[1+NativeCreatureModel.MaxLimbs*NativeMovementWeights.PolicyLimbOutputs];r[0]=Dense(c.policyContext,w.frequency,1,0)[0];for(int l=0;l<limbs;l++){float[] x=Dense(Concat(c.state[3][l],c.global),w.limbPolicy,NativeMovementWeights.PolicyLimbOutputs,0);Array.Copy(x,0,r,1+l*4,4);}return r;}
    private static float Value(NativeMovementObservation o,NativeMovementWeights w)=>ValueFromCache(ForwardGraph(o,w),w);private static float ValueFromCache(NativeGraphCache c,NativeMovementWeights w)=>Dense(c.policyContext,w.value,1,0)[0];
    private static float PredictDisagreement(NativeGraphCache c,float[] actions,NativeMovementWeights w){float[] input=Concat(c.pooled,ActionsWithHorizon(actions,c.observation.limbCount,1));float[][] p={Dense(input,w.m3Head0,NativeMovementWeights.TargetSize,0,w.m3Bias0),Dense(input,w.m3Head1,NativeMovementWeights.TargetSize,0,w.m3Bias1),Dense(input,w.m3Head2,NativeMovementWeights.TargetSize,0,w.m3Bias2)};float sum=0f;for(int i=0;i<NativeMovementWeights.TargetSize;i++){float m=(p[0][i]+p[1][i]+p[2][i])/3f;sum+=(p[0][i]-m)*(p[0][i]-m)+(p[1][i]-m)*(p[1][i]-m)+(p[2][i]-m)*(p[2][i]-m);}return Mathf.Min(CuriosityCap,sum/(NativeMovementWeights.TargetSize*3f));}
    private static float[] PhysicalTarget(NativeMovementTransition t){float[] y=new float[NativeMovementWeights.TargetSize];y[0]=t.torsoDeltaX/BodyMorphologyRules.TorsoWidth;y[1]=t.torsoDeltaY/BodyMorphologyRules.TorsoHeight;y[2]=Mathf.Sin(t.headingDelta*Mathf.Deg2Rad);y[3]=Mathf.Cos(t.headingDelta*Mathf.Deg2Rad)-1f;y[4]=t.nextObservation?.history?.LastOrDefault(x=>x!=null)?.torsoWithoutGoal?[2]??0f;y[5]=t.angularVelocityDelta/720f;NativeObservation a=t.observation?.history?.LastOrDefault(x=>x!=null),b=t.nextObservation?.history?.LastOrDefault(x=>x!=null);for(int l=0;l<Mathf.Min(t.observation?.limbCount??0,NativeCreatureModel.MaxLimbs);l++){int o=6+l*10,j=l*NativeCreatureModel.JointFeatureSize;y[o]=(b?.jointFeatures?[j]??0f)-(a?.jointFeatures?[j]??0f);y[o+1]=(b?.jointFeatures?[j+1]??0f)-(a?.jointFeatures?[j+1]??0f);for(int k=0;k<4;k++)y[o+2+k]=(b?.jointFeatures?[j+9+k]??0f)-(a?.jointFeatures?[j+9+k]??0f);for(int k=0;k<3;k++)y[o+6+k]=b?.jointFeatures?[j+4+k]??0f;y[o+9]=(b?.jointFeatures?[j+21]??0f)*(y[o+6]>.5f?1f:0f);}return y;}
    private static float[] ActionsWithHorizon(float[] a,int limbs,int horizon){float[] r=new float[NativeCreatureModel.MaxLimbs+3];for(int i=0;i<Mathf.Min(limbs,a?.Length??0);i++)r[i]=a[i]/8f;r[NativeCreatureModel.MaxLimbs+(horizon>=10?2:horizon>=5?1:0)]=1f;return r;}
    private static void SampleInto(List<NativeMovementTransition> source,List<NativeMovementTransition> target,int count){if(source.Count==0)return;int start=Math.Max(0,source.Count-count);for(int i=start;i<source.Count;i++)target.Add(source[i]);}
    private static Dictionary<string,float[]> Zero(NativeMovementWeights w)=>w.Parameters().ToDictionary(p=>p.Key,p=>new float[p.Value.Length]);private static void Scale(Dictionary<string,float[]> g,float s){foreach(float[] a in g.Values)for(int i=0;i<a.Length;i++)a[i]*=s;}
    private static void ApplyAdam(NativeMovementWeights w,Dictionary<string,float[]> g,NativeOptimizerState optimizer,float rate,float maxNorm){float norm=Mathf.Sqrt(g.Values.Sum(a=>a.Sum(x=>x*x))),scale=norm>maxNorm?maxNorm/norm:1f;optimizer.step++;float c1=1f-Mathf.Pow(.9f,optimizer.step),c2=1f-Mathf.Pow(.999f,optimizer.step);foreach(var p in w.Parameters()){var s=optimizer.Get(p.Key,p.Value.Length);for(int i=0;i<p.Value.Length;i++){float x=g[p.Key][i]*scale;s.first[i]=.9f*s.first[i]+.1f*x;s.second[i]=.999f*s.second[i]+.001f*x*x;p.Value[i]-=rate*(s.first[i]/c1)/(Mathf.Sqrt(s.second[i]/c2)+1e-8f);}}if(!w.IsFinite())throw new InvalidOperationException("v26 learner produced non-finite weights");}
    private static void BackwardGraph(NativeGraphCache c,float[] pooledGradient,NativeMovementWeights w,Dictionary<string,float[]> g){int n=c.state[3].Length;float[][] grad=Enumerable.Range(0,n).Select(_=>(float[])pooledGradient.Clone()).ToArray();for(int l=0;l<n;l++)for(int h=0;h<NativeMovementWeights.Width;h++)grad[l][h]/=Mathf.Max(1,n);BackwardGraph(c,grad,w,g);}
    private static void BackwardGraph(NativeGraphCache c,float[][] grad,NativeMovementWeights w,Dictionary<string,float[]> g){int n=grad.Length,W=NativeMovementWeights.Width;for(int round=3;round>=1;round--){float[][] previous=Enumerable.Range(0,n).Select(_=>new float[W]).ToArray();for(int l=0;l<n;l++){float[] dz=new float[W];for(int h=0;h<W;h++)dz[h]=grad[l][h]*(1f-c.state[round][l][h]*c.state[round][l][h]);float[] self=DenseBackward(c.state[round-1][l],dz,w.messageSelf,g["messageSelf"],g["messageBias"]);Add(previous[l],self);int p=c.parent[l];if(p>=0)Add(previous[p],DenseBackward(c.state[round-1][p],dz,w.messageParent,g["messageParent"],null));int children=Enumerable.Range(0,n).Count(k=>c.parent[k]==l);if(children>0){float[] avg=new float[W];for(int k=0;k<n;k++)if(c.parent[k]==l)Add(avg,c.state[round-1][k]);for(int h=0;h<W;h++)avg[h]/=children;float[] cg=DenseBackward(avg,dz,w.messageChild,g["messageChild"],null);for(int k=0;k<n;k++)if(c.parent[k]==l)for(int h=0;h<W;h++)previous[k][h]+=cg[h]/children;}}grad=previous;}for(int l=0;l<n;l++){float[] dz=new float[W];for(int h=0;h<W;h++)dz[h]=grad[l][h]*(1f-c.state[0][l][h]*c.state[0][l][h]);DenseBackward(c.input[l],dz,w.nodeInput,g["nodeInput"],g["nodeBias"]);}}
    private static float[] DenseBackward(float[] input,float[] outputGradient,float[] weights,float[] weightGradient,float[] biasGradient){DenseBackward(input,outputGradient,weights,weightGradient,biasGradient,out float[] result);return result;}private static void DenseBackward(float[] input,float[] outputGradient,float[] weights,float[] weightGradient,float[] biasGradient,out float[] inputGradient){int outputs=outputGradient.Length;inputGradient=new float[input.Length];for(int i=0;i<input.Length;i++)for(int o=0;o<outputs;o++){int k=i*outputs+o;weightGradient[k]+=input[i]*outputGradient[o];inputGradient[i]+=weights[k]*outputGradient[o];}if(biasGradient!=null)for(int o=0;o<outputs;o++)biasGradient[o]+=outputGradient[o];}
    private static float[] Dense(float[] input,float[] weights,int outputs,int biasOffset,float[] bias=null){float[] r=new float[outputs];for(int i=0;i<input.Length;i++)for(int o=0;o<outputs;o++)r[o]+=input[i]*weights[i*outputs+o];if(bias!=null)for(int o=0;o<outputs;o++)r[o]+=bias[biasOffset+o];return r;}private static float[] Activate(float[] x){for(int i=0;i<x.Length;i++)x[i]=(float)Math.Tanh(x[i]);return x;}private static float[] Concat(float[] a,float[] b){float[] r=new float[a.Length+b.Length];Array.Copy(a,r,a.Length);Array.Copy(b,0,r,a.Length,b.Length);return r;}private static void Add(float[] target,float[] source){for(int i=0;i<Math.Min(target.Length,source.Length);i++)target[i]+=source[i];}private static float Dot(float[] a,float[] b){float r=0f;for(int i=0;i<Math.Min(a.Length,b.Length);i++)r+=a[i]*b[i];return r;}private static float Sigmoid(float x)=>1f/(1f+Mathf.Exp(-Mathf.Clamp(x,-20f,20f)));private static float Gaussian(ref NativeDeterministicRng r){float a=Mathf.Max(1e-7f,r.NextFloat()),b=r.NextFloat();return Mathf.Sqrt(-2f*Mathf.Log(a))*Mathf.Cos(2f*Mathf.PI*b);}
    public void Dispose(){stopping=true;signal.Set();if(worker.IsAlive)worker.Join(2000);signal.Dispose();}
